import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"25、【无妄】 震下乾上","description":"周易尚氏学 - 25、【无妄】 震下乾上","frontmatter":{"title":"25、【无妄】 震下乾上","description":"周易尚氏学 - 25、【无妄】 震下乾上"},"headers":[],"relativePath":"zh/classics/shangshi/030.md","filePath":"zh/classics/shangshi/030.md"}'),h={name:"zh/classics/shangshi/030.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_25、【无妄】-震下乾上" tabindex="-1">25、【无妄】 震下乾上 <a class="header-anchor" href="#_25、【无妄】-震下乾上" aria-label="Permalink to “25、【无妄】 震下乾上”">​</a></h1><p>震巽为草木为禾稼。下艮为火。故焦京王充皆以无望为大旱之卦。而乾为年。巽为人。年收失望。故曰无妄。元亨者。谓乾元通也。初当位。前临重阴。五中正。故乾元以通。利贞者。利于贞定也。正亦定也。匪正谓三上。三上不当位。妄动。故有眚。眚病也。巽为疾病。其匪正有眚者。言不能贞定而躁动。即有眚也。不利有攸往。仍以动为戒也。震为决躁。躁动于内。外与刚健遇。必无幸矣。故曰不利有攸往。妄释文云。马郑玉肃皆作望。谓无所希望也。按此训最古。史记春申君传云。世有毋望之福。又有毋望之祸。今君处毋望之世。事毋望之主。是自战国即读为望。作毋亡。妄古文妄之省。王陶庐云。妄望同音相借。大戴礼文王篇故得望誉。望誉即妄誉。史迁受易于杨何。固无误也。又按杂卦云。无妄灾也。故太玄拟无妄为去。汉书谷永传。遭无妄之卦运。应劭云。天必先云而后雷。雷而后雨。今无云而雷。无妄者无所望也。万物无所望于天。灾异之最大者也。后汉崔篆传。值无妄之世。王充论衡。易无妄之应。水旱之至。蔡邕邓皇后溢议。消无妄之运。举两汉之人。无作虚妄及失妄解者。无妄犹孟子所谓不虞也。六爻爻辞皆不虞之事。又无妄灾也。以艮火象失传之故。皆莫知灾之自来。而焦京以无妄为大旱。易林屡见。详焦氏易诂之卦。其故自荀虞莫明矣。卞斌云。匪正宜作匪百。经无作正者。虞翻知巽为禾稼。而不知艮火象。故不知大旱之义。斥京氏为非。诂为亡失。不亡失则卦吉矣。然何以解于杂卦之无妄灾及家传。象传曰。无妄之往何之矣。天命不右行矣哉。无妄若为吉卦。而曰天命不右。曰无所往。有是理乎。虞翻最忌郑学。郑作望故驳之。其所谓俗儒。殆即指郑。后崔憬何妥竞作虚妄解。益与传背。世岂有忠信之人。天命不右。往无所合者哉。害理乱道。莫斯为甚。</p><p>彖曰。无妄。刚自外来。而为主于内。动而健。刚中而应。大亨以正。天之命也。其匪正有音。不利有攸往。无妄之往。何之矣。天命不佑。行矣哉。</p><p>震为主谓初也。先儒谓遁上来初。故曰自外来。震为躁卦。躁动于内。而外遇乾刚。故所之不合。五刚中。二有应。故曰刚中而应。大亨者。元亨也。以正者。利贞也。元亨利贞。循环来往。天命固如斯也。乾为天。巽为命也。临传云。大亨以正。天之道也。天命与天道同也。故时当元亨而动。时当利贞。即不宜动。不宜动而强动。违天者也。违天而行。天所不福。右福也。何之者。言时值无望。无往而可也。盖易之旨。阳刚不宜在外。在外则气穷。有阳九之户（加九？）。故卦辞以行为戒。以贞定为主。</p><p>象曰。天下雷行。物与无妄。先王以茂对时育万物。</p><p>与举也。天下雷行。万物震恐。举失其求望。茂与懋通。勉也。对答也。言因雷而勉答大威。傅亮文云。只服住命。茂对天休。潘岳秋兴赋。览花莳时之育兮。是茂对连文。时育连文。古读如是。释文作茂对时。非也。艮为时。震巽皆为草莽。而震为生。故曰时育万物。即严畏天命。顺时育物也。象有以相反为义者。如蛊曰振民育德。剥曰上以厚下安宅。明夷曰用晦而明。及此皆是也。虞仲翔不知此旨。据象言时育。证万物皆死之非。审如是也。将蛊曰振育。亦可谓之不蛊。剥曰安宅。亦可谓之非剥。尚可通乎。</p><p>初九。无妄。往吉。</p><p>阳遇阴则通。故往吉。</p><h3 id="象曰。无妄之往。得志也。" tabindex="-1">象曰。无妄之往。得志也。 <a class="header-anchor" href="#象曰。无妄之往。得志也。" aria-label="Permalink to “象曰。无妄之往。得志也。”">​</a></h3><p>得志谓往遇二阴也。大畜九三云。上合志。涣九二云。得愿。上皆无应。皆以前遇二阴。虞翻不知此为易不刊之定理。命四爻变阴。初得应释得志。清儒从之。讹误至今。</p><p>六二。不耕获，不菑畲，则利有攸往。</p><p>获悦文刈谷也。时小雅于此苗（中　）亩。蔬苗（中　）灾也。始灾杀其草木也，故说文云。不耕田也。畬文三岁治田。时周颂。如何新畬。传一岁曰畜。二岁曰新田。三岁日畬。尔雅同。独郑康成及虞翻谓田二岁曰畬。皆以在二爻岂知诗明曰新畬。是第一年苗（中　）田。第二年便为新田。然尚未柔和也。故第三年为畬田。观诗不曰畬新。而曰新畬。郑虞误也。盖二居艮震之间。震为耕为苗（中　）乃前遇艮。艮止。故不耕不苗。艮手为获。艮成终。为畬。不耕而获。不苗（中　）而畬。为必无望之事。故象以未富为释。据坊记引则为凶字。又据说文引畬下多田字。段玉裁以为即凶之形讹字。然则则为凶字无疑。乃王注谓不耕而获。不苗（中　）而畬。只代终。不造始。臣道固如是也。故利往。如王诂是亦获亦畬也。与象未富之义不合。按易林无妄之讼云。不耕而获。家食不给。谓既不耕。获必无得。故家食不给。读虽与王同。而义则与小象不背矣。又礼坊记引此郑彼注云言必先耕乃得获。先苗（中　）乃得畬。安有无事而取利者乎。皆正诂。宜从。二有应。故利往。此自为一义。与上二句不相属。与困彖同。</p><h3 id="象曰。不耕获。未富也。" tabindex="-1">象曰。不耕获。未富也。 <a class="header-anchor" href="#象曰。不耕获。未富也。" aria-label="Permalink to “象曰。不耕获。未富也。”">​</a></h3><p>六三。无妄之灾。或系之牛。行人之得。邑人之灾。</p><p>无妄之灾。犹不虞之灾也。艮为牛。象失传。详焦氏易诂补遗。粪为系。故或系之牛。震为行为人。巽为盗。故行人之得。艮为邑。良火故曰灾。言或系之牛。被行人牵去。居者反有盗嫌。遭诘捕之祸也。爻辞取象。神妙已极。乃自艮牛民火象失传。自虞翻以来。皆用卦变。致妙用全失。盖三不当位。而巽伏为盗。象失传。详焦氏易诂补遗故有是象。灾之无妄。莫过于是。</p><h3 id="象曰。行人得牛。邑人灾也。" tabindex="-1">象曰。行人得牛。邑人灾也。 <a class="header-anchor" href="#象曰。行人得牛。邑人灾也。" aria-label="Permalink to “象曰。行人得牛。邑人灾也。”">​</a></h3><p>九四。可贞。无咎。</p><p>阳遇阳则窒。下又无应。不宜于动。故曰可贞。贞定也。然得重阴履之。故亦无咎。</p><h3 id="象曰。可贞无咎。固有之也。" tabindex="-1">象曰。可贞无咎。固有之也。 <a class="header-anchor" href="#象曰。可贞无咎。固有之也。" aria-label="Permalink to “象曰。可贞无咎。固有之也。”">​</a></h3><p>固有即谓二阴。虞翻亦用卦变说之。非。</p><p>九五。无安之症。勿药有喜。</p><p>巽为疾。为草莽。故为药。无妄之疾。言疾之愈已失望。乃勿药而愈。其喜可知。五应在二。震为笑乐。故有喜也。勿药者。言巽药为艮为所焚也。</p><h3 id="象曰。无妄之药。不可试也。" tabindex="-1">象曰。无妄之药。不可试也。 <a class="header-anchor" href="#象曰。无妄之药。不可试也。" aria-label="Permalink to “象曰。无妄之药。不可试也。”">​</a></h3><p>不可试。言此为事之偶然。非所期望。不可尝试。盖五虽当位有应。然承乘皆阳。未为全吉。</p><p>上九。无安。行有眚。无攸利。</p><p>上应在三。巽为疾病。为眚。为利。然四五遇敌。故行有眚而无所利也。</p><h3 id="象曰。无妾之行。穷之灾也。" tabindex="-1">象曰。无妾之行。穷之灾也。 <a class="header-anchor" href="#象曰。无妾之行。穷之灾也。" aria-label="Permalink to “象曰。无妾之行。穷之灾也。”">​</a></h3>',27)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
